function stageFor(correct){return correct>=50?4:correct>=25?3:correct>=10?2:1;}
function stageInfo(correct){return STAGES[stageFor(correct)-1];}
function unlockStatus(profile={},attempts=0,previous={}){if(previous.unlockedAt)return{unlocked:true,unlockedAt:previous.unlockedAt,persisted:true};const scores=TERRITORIES.map(id=>profile[id]),evaluated=scores.filter(Number.isFinite),minimum=evaluated.length?Math.min(...evaluated):0,passed=evaluated.length===TERRITORIES.length&&minimum>=25&&attempts>=350;return{unlocked:passed,unlockedAt:passed?Date.now():null,persisted:false,evaluated:evaluated.length,minimum,attempts};}
function pickQuestion({profile={},correct=0,counts={},recent=[],lastTerritory=null}={},random=Math.random){const stage=stageFor(correct),eligible=QUESTIONS.filter(item=>item.minStage<=stage&&item.minStage>=Math.max(1,stage-1)&&!recent.includes(item.id)&&item.territory!==lastTerritory),fallback=QUESTIONS.filter(item=>item.minStage<=stage&&!recent.includes(item.id)),pool=eligible.length?eligible:fallback;const territoryCounts=TERRITORIES.map(id=>Number(counts[id]||0)),minCount=Math.min(...territoryCounts),scored=pool.map(item=>{const score=Number.isFinite(profile[item.territory])?profile[item.territory]:50,weakness=1+(100-score)/45,balance=Number(counts[item.territory]||0)===minCount?1.8:1;return{item,weight:weakness*balance};});let roll=random()*scored.reduce((sum,row)=>sum+row.weight,0);for(const row of scored){roll-=row.weight;if(roll<=0)return row.item;}return scored.at(-1)?.item||QUESTIONS[0];}
