function emptyStats(){return{unlockedAt:null,attempts:0,totalCorrect:0,best:0,bestAt:null,lastRun:null,territoryTotals:{}};}
function finishRun(stats,run,at=Date.now()){const next={...emptyStats(),...(stats||{})},result={correct:run.correct||0,errors:run.errors||0,stage:stageFor(run.correct||0),durationMs:Math.max(0,at-run.startedAt),at,territoryCounts:{...(run.counts||{})}};next.attempts++;next.totalCorrect+=result.correct;next.lastRun=result;if(result.correct>next.best){next.best=result.correct;next.bestAt=at;}for(const[id,count]of Object.entries(result.territoryCounts))next.territoryTotals[id]=Number(next.territoryTotals[id]||0)+count;return{stats:next,result};}
